package com.intermarche.backoffice.engine.fieldops;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.order.*;import com.intermarche.backoffice.domain.util.DateTimeProvider;
import com.intermarche.backoffice.engine.stock.*;import com.intermarche.backoffice.engine.operator.*;
import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import jakarta.transaction.Transactional;import jakarta.ws.rs.*;
import com.intermarche.backoffice.engine.catalog.ProductMeasure;
import java.math.BigDecimal;import java.util.*;
@ApplicationScoped @Transactional
public class ProductReturnService {
 @Inject jakarta.persistence.EntityManager em;@Inject FieldOperationsService field;@Inject StockCommands receipts;@Inject TemporalStockService stocks;@Inject StockTraceLedger ledger;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="ProductReturnInput") public static class Input {public Long storeId,returnId,lineId,dispositionId,productId,locationId,shipmentId,shipmentLineId,lotId,serialId;public String requestKey,reference,reason,inspection,decision,action;public BigDecimal quantity;public Long expectedRevision;}
 private Store scoped(Input i){if(i==null)throw new BadRequestException();FieldOperationsService.key(i.requestKey);return field.store(i.storeId,true);}
 private ProductReturn dossier(Store s,Long key){var r=ProductReturn.<ProductReturn>find("id=?1 and store=?2",key,s).firstResult();if(r==null)throw new NotFoundException();return r;}
 private void expected(ProductReturn r,Input i){if(i.expectedRevision==null||r.revisionNumber!=i.expectedRevision)throw new OperatorFailure(409,"STALE_RETURN","Le retour a changé : actualisez avant de confirmer.");}
 private BaseLocation location(Store s,Long key,Product p){BaseLocation l=BaseLocation.findById(key);if(l==null||!(org.hibernate.Hibernate.unproxy(l) instanceof StoreShelfLocation||org.hibernate.Hibernate.unproxy(l) instanceof WarehouseShelfLocation||org.hibernate.Hibernate.unproxy(l) instanceof BufferToteStockLocation))throw new BadRequestException("Choisissez une adresse physique configurée dans le bâtiment ou un bac de buffer.");var b=BaseLocation.findBuildingsByLocations(List.of(l));if(b.size()!=1||!Objects.equals(id(Building.findStoreByBuildingId(id(b.getFirst()))),s.id)||l.product!=null&&!id(l.product).equals(id(p)))throw new BadRequestException("Adresse hors périmètre ou affectée à un autre produit");return l;}
 private void history(Store s,ProductReturn r,String action,String reason){var h=new LogisticsHistory();h.store=s;h.subjectType="RETURN";h.subjectId=r.id;h.action=action;h.reason=reason;h.actor=field.actor();h.snapshot=field.encode(view(r));h.persist();}
 public Object receive(Input i){Store s=scoped(i);String fp=field.hash(i);var old=receipts.previous(s,i.requestKey,fp);if(old!=null)return receipts.value(old);FieldOperationsService.text(i.reason,2000);FieldOperationsService.text(i.reference,255);Product p=Product.findById(i.productId);if(p==null)throw new NotFoundException();BigDecimal qty=LogisticsQuantity.positive(i.quantity,p.productType);if(qty.signum()<=0)throw new BadRequestException("Quantité positive requise");BaseLocation l=location(s,i.locationId,p);
  ManufacturerLot lot=i.lotId==null?null:ManufacturerLot.findById(i.lotId);ProductSerial serial=i.serialId==null?null:ProductSerial.findById(i.serialId);if(i.lotId!=null&&lot==null||i.serialId!=null&&serial==null||lot!=null&&(!id(lot.store).equals(s.id)||!id(lot.product).equals(p.id))||serial!=null&&(!id(serial.store).equals(s.id)||!id(serial.product).equals(p.id)||lot!=null&&!Objects.equals(serial.lot==null?null:id(serial.lot),id(lot))))throw new BadRequestException("Lot ou série hors du produit/magasin");if(serial!=null&&lot==null)lot=serial.lot;if(serial!=null){if(qty.compareTo(BigDecimal.ONE)!=0)throw new BadRequestException("Une unité par série");BigDecimal balance=em.createQuery("select coalesce(sum(m.quantity),0) from StockMovement m where m.segment.serial=?1",BigDecimal.class).setParameter(1,serial).getSingleResult();if(balance.signum()!=0)throw new OperatorFailure(409,"SERIAL_ALREADY_STOCKED","Cette série est déjà physiquement localisée");}
  var r=new ProductReturn();r.store=s;r.reference=i.reference.trim();r.reason=i.reason.trim();r.reportedBy=field.actor();r.receivedAt=DateTimeProvider.now();
  ShipmentLine origin=null;if(i.shipmentId!=null){r.shipment=Shipment.find("id=?1 and store=?2",i.shipmentId,s).firstResult();if(r.shipment==null)throw new NotFoundException();if(i.shipmentLineId==null)throw new BadRequestException("Choisissez la ligne expédiée retournée");origin=r.shipment.lines.stream().filter(x->x.id.equals(i.shipmentLineId)).findFirst().orElseThrow(NotFoundException::new);if(!id(origin.pickedItem.product).equals(p.id))throw new BadRequestException("Le produit ne correspond pas à la ligne expédiée");BigDecimal previous=ProductReturnLine.<ProductReturnLine>list("shipmentLine",origin).stream().map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);if(previous.add(qty).compareTo(origin.quantity)>0)throw new BadRequestException("Le cumul retourné dépasse la quantité expédiée");}else if(i.shipmentLineId!=null)throw new BadRequestException("Expédition requise pour cette ligne");
  r.persistAndFlush();r.code="RET-"+s.id+"-"+r.id;var segment=ledger.segment(stocks.account(s.id,p.id),l,null,lot,serial,"RETURN_PENDING");ledger.entry(segment,qty,"return:"+r.id,"receipt","PRODUCT_RETURN",r.receivedAt);var line=new ProductReturnLine();line.productReturn=r;line.product=p;line.segment=segment;line.shipmentLine=origin;line.quantity=qty;line.persistAndFlush();history(s,r,"RECEIVED",r.reason);return receipts.record(s,i.requestKey,fp,"RECEIVE_RETURN",view(r));
 }
 public Object inspect(Input i){Store s=scoped(i);String fp=field.hash(i);var old=receipts.previous(s,i.requestKey,fp);if(old!=null)return receipts.value(old);var r=dossier(s,i.returnId);expected(r,i);FieldOperationsService.text(i.reason,2000);if(!Set.of("GOOD","DAMAGED","UNCERTAIN").contains(i.inspection==null?"":i.inspection))throw new BadRequestException("Résultat d’inspection requis");var l=ProductReturnLine.<ProductReturnLine>find("id=?1 and productReturn=?2",i.lineId,r).firstResult();if(l==null)throw new NotFoundException();if(!"PENDING".equals(l.inspection))throw new OperatorFailure(409,"RETURN_ALREADY_INSPECTED","L’inspection est déjà enregistrée");l.inspection=i.inspection;l.inspectedBy=field.actor();l.inspectionReason=i.reason;l.inspectedAt=DateTimeProvider.now();r.state="INSPECTED";r.revisionNumber++;history(s,r,"INSPECTED",i.reason);return receipts.record(s,i.requestKey,fp,"INSPECT_RETURN",view(r),List.of(com.intermarche.backoffice.engine.operator.OperationQuantities.amount("INSPECTED",l.product,l.id,l.quantity)));}
 public Object plan(Input i){field.requireManager();Store s=scoped(i);String fp=field.hash(i);var old=receipts.previous(s,i.requestKey,fp);if(old!=null)return receipts.value(old);var r=dossier(s,i.returnId);expected(r,i);FieldOperationsService.text(i.reason,2000);var l=ProductReturnLine.<ProductReturnLine>find("id=?1 and productReturn=?2",i.lineId,r).firstResult();if(l==null)throw new NotFoundException();if("PENDING".equals(l.inspection))throw new BadRequestException("Inspectez les marchandises avant de choisir leur destination");if(!Set.of("RESTOCK","QUARANTINE","SCRAP").contains(i.decision==null?"":i.decision))throw new BadRequestException("Décision inconnue");if("RESTOCK".equals(i.decision)&&!"GOOD".equals(l.inspection))throw new BadRequestException("Seuls les produits inspectés conformes peuvent être remis en stock");BigDecimal qty=LogisticsQuantity.positive(i.quantity,l.product.productType);BigDecimal allocated=ReturnDisposition.<ReturnDisposition>list("line",l).stream().map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);if(qty.signum()<=0||allocated.add(qty).compareTo(l.quantity)>0)throw new BadRequestException("La ventilation dépasse le retour reçu");var d=new ReturnDisposition();d.line=l;d.quantity=qty;d.decision=i.decision;d.reason=i.reason;d.decidedBy=field.actor();if(!"SCRAP".equals(i.decision))d.destination=location(s,i.locationId,l.product);if("RESTOCK".equals(i.decision)){var candidate=ledger.segment(l.segment.account,d.destination,null,l.segment.lot,l.segment.serial,"AVAILABLE");StockQualityRules.requireSegment(candidate,"RECEIPT");}d.persistAndFlush();r.state="TO_ORIENT";r.revisionNumber++;history(s,r,"DISPOSITION_PLANNED",i.reason);return receipts.record(s,i.requestKey,fp,"PLAN_RETURN",view(r),List.of(com.intermarche.backoffice.engine.operator.OperationQuantities.amount("RETURN_ORIENTED",l.product,l.id,d.quantity)));}
 public Object execute(Input i){Store s=scoped(i);String fp=field.hash(i);var old=receipts.previous(s,i.requestKey,fp);if(old!=null)return receipts.value(old);var r=dossier(s,i.returnId);expected(r,i);var d=ReturnDisposition.<ReturnDisposition>find("id=?1 and line.productReturn=?2",i.dispositionId,r).firstResult();if(d==null)throw new NotFoundException();var source=d.line.segment;String op="return-disposition:"+d.id;var now=DateTimeProvider.now();
  if("PICK".equals(i.action)&&"PLANNED".equals(d.state)){requireBalance(source,d.quantity);if("SCRAP".equals(d.decision)){field.requireManager();ledger.entry(source,d.quantity.negate(),op,"scrap","RETURN_SCRAP",now);d.state="DONE";d.completedAt=now;}else{var building=BaseLocation.findBuildingsByLocations(List.of(source.location)).getFirst();var address=new ReturnTransitLocation();address.product=d.line.product;address.area="RETOURS";address.aisle="TRANSIT";address.unit="RET";address.elevation="1";address.position="1";address.locationCode="TRANSIT-RET-"+d.id;address.persistAndFlush();building.locations.add(address);var transit=ledger.segment(source.account,address,null,source.lot,source.serial,"RETURN_TRANSIT");transit.receivedAt=source.receivedAt;ledger.move(source,transit,d.quantity,op,"pick","RETURN_MOVE");d.transitSegment=transit;d.state="TRANSIT";d.pickedAt=now;}}
  else if("RECEIVE".equals(i.action)&&"TRANSIT".equals(d.state)){requireBalance(d.transitSegment,d.quantity);var target=ledger.segment(source.account,d.destination,null,source.lot,source.serial,"RESTOCK".equals(d.decision)?"AVAILABLE":"QUARANTINED");if("RESTOCK".equals(d.decision))StockQualityRules.requireSegment(target,"RECEIPT");target.receivedAt=source.receivedAt;ledger.move(d.transitSegment,target,d.quantity,op,"putaway","RETURN_PUTAWAY");d.state="DONE";d.completedAt=now;}
  else throw new OperatorFailure(409,"RETURN_PHASE_CHANGED","Cette action ne correspond plus à la phase du retour");d.performedBy=field.actor();d.revisionNumber++;r.revisionNumber++;field.flush();var lines=ProductReturnLine.<ProductReturnLine>list("productReturn",r);boolean complete=lines.stream().allMatch(l->ReturnDisposition.<ReturnDisposition>list("line",l).stream().filter(x->"DONE".equals(x.state)).map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(l.quantity)==0);r.state=complete?"COMPLETED":"TO_ORIENT";history(s,r,"DISPOSITION_"+i.action,d.reason);return receipts.record(s,i.requestKey,fp,"EXECUTE_RETURN",view(r));}
 private void requireBalance(StockSegment segment,BigDecimal quantity){var balance=em.createQuery("select coalesce(sum(m.quantity),0) from StockMovement m where m.segment=?1 and m.effectiveAt<=?2",BigDecimal.class).setParameter(1,segment).setParameter(2,DateTimeProvider.now()).getSingleResult();if(balance.compareTo(quantity)<0)throw new OperatorFailure(409,"RETURN_STOCK_CHANGED","Les marchandises retournées ne sont plus à cette adresse : vérifiez leur localisation.");}
 public Object list(Long storeId,String state,long before,int limit){Store s=field.store(storeId,false);if(limit<1||limit>100||before<0||state!=null&&!state.isBlank()&&!Set.of("RECEIVED","INSPECTED","TO_ORIENT","COMPLETED").contains(state))throw new BadRequestException();String where="store=?1";var args=new ArrayList<Object>();args.add(s);if(state!=null&&!state.isBlank()){args.add(state);where+=" and state=?"+args.size();}if(before>0){args.add(before);where+=" and id<?"+args.size();}var rows=ProductReturn.<ProductReturn>find(where+" order by id desc",args.toArray()).range(0,limit).list();return Map.of("items",rows.stream().limit(limit).map(this::summary).toList(),"hasMore",rows.size()>limit,"nextBefore",rows.isEmpty()?before:rows.get(Math.min(limit,rows.size())-1).id);}
 Map<String,Object> summary(ProductReturn r){var v=new LinkedHashMap<String,Object>();v.put("id",r.id);v.put("code",r.code);v.put("reference",r.reference);v.put("state",r.state);v.put("revision",r.revisionNumber);v.put("receivedAt",r.receivedAt);v.put("reason",r.reason);v.put("shipmentId",r.shipment==null?null:id(r.shipment));return v;}
 public Object locations(Long storeId,Long productId){var store=field.store(storeId,false);return em.createQuery("select l.id,l.locationCode,b.buildingCode,type(b) from Store s join s.buildings b join b.locations l where s=?1 and (l.product is null or l.product.id=?2) and type(l) in (StoreShelfLocation,WarehouseShelfLocation,BufferToteStockLocation) order by b.buildingCode,l.locationCode",Object[].class).setParameter(1,store).setParameter(2,productId).getResultList().stream().map(r->Map.of("id",r[0],"code",r[1],"buildingCode",r[2],"buildingType",((Class<?>)r[3]).getSimpleName())).toList();}
 public Object identities(Long storeId,Long productId,String q){Store s=field.store(storeId,false);String search=q==null?"":q.trim();if(search.length()>100)throw new BadRequestException();return Map.of("lots",ManufacturerLot.<ManufacturerLot>find("store=?1 and product.id=?2 and lower(code) like ?3 order by code",s,productId,"%"+search.toLowerCase(Locale.ROOT).replace("%","").replace("_","")+"%").range(0,99).list().stream().map(l->Map.of("id",l.id,"code",l.code)).toList(),"serials",ProductSerial.<ProductSerial>find("store=?1 and product.id=?2 and lower(code) like ?3 order by code",s,productId,"%"+search.toLowerCase(Locale.ROOT).replace("%","").replace("_","")+"%").range(0,99).list().stream().map(x->Map.of("id",x.id,"code",x.code)).toList());}
 public Object read(Long storeId,Long key){return view(dossier(field.store(storeId,false),key));}
 Map<String,Object> view(ProductReturn r){var v=summary(r);v.put("canManage",field.manager());v.put("lines",ProductReturnLine.<ProductReturnLine>list("select l from ProductReturnLine l join fetch l.product join fetch l.segment s join fetch s.location left join fetch s.lot left join fetch s.serial where l.productReturn=?1 order by l.id",r).stream().map(l->{var row=new LinkedHashMap<String,Object>();row.put("id",l.id);row.put("productId",id(l.product));row.put("name",l.product.name);row.put("ean",l.product.ean);row.put("unit",l.product.productType==ProductType.WEIGHT?"kg":l.product.productType==ProductType.VOLUME?"L":"pcs");row.put("quantity",l.quantity);row.put("inspection",l.inspection);row.put("inspectionReason",l.inspectionReason);row.put("address",l.segment.location.locationCode);row.put("lot",l.segment.lot==null?null:l.segment.lot.code);row.put("serial",l.segment.serial==null?null:l.segment.serial.code);row.put("dispositions",ReturnDisposition.<ReturnDisposition>list("select d from ReturnDisposition d left join fetch d.destination where d.line=?1 order by d.id",l).stream().map(d->{var x=new LinkedHashMap<String,Object>();x.put("id",d.id);x.put("quantity",d.quantity);x.put("decision",d.decision);x.put("state",d.state);x.put("address",d.destination==null?null:d.destination.locationCode);x.put("reason",d.reason);return x;}).toList());return row;}).toList());v.put("history",LogisticsHistory.<LogisticsHistory>find("store=?1 and subjectType='RETURN' and subjectId=?2 order by id desc",r.store,r.id).range(0,99).list().stream().map(h->Map.of("action",h.action,"actor",h.actor,"reason",h.reason,"at",h.createdAt)).toList());return v;}
}
